1→/**
 * Direcciones Ethereum: derivación desde la clave pública y checksum EIP-55.
 *
 * Fuente normativa: ERC-55 / EIP-55 («Mixed-case checksum address encoding») y Keccak-256.
 * Spec del proyecto: HU-06-02 RN-4 (dirección = últimos 20 bytes de `Keccak-256(X ‖ Y)`,
 * serializada como `0x` + 40 hex con checksum EIP-55) y RN-7 (uso en Sepolia; el formato
 * de dirección es agnóstico a la red).
 */
import { keccak_256 } from '@noble/hashes/sha3.js';
10→import { validationError } from '../../shared/errors.js';

/** `0x` + 40 dígitos hexadecimales, en cualquier capitalización. */
const ADDRESS_RE = /^0x[0-9a-fA-F]{40}$/u;

/** Longitud en bytes de una dirección Ethereum (EOA de 20 bytes). */
export const ADDRESS_BYTES = 20;

const ascii = new TextEncoder();

20→function toHex(bytes: Uint8Array): string {
  let hex = '';
  for (const byte of bytes) hex += byte.toString(16).padStart(2, '0');
  return hex;
}

/** `true` si la cadena tiene la forma `0x` + 40 hex (sin mirar el checksum). */
export function isValidAddressFormat(address: string): boolean {
  return ADDRESS_RE.test(address);
}
30→
/**
 * Aplica el checksum EIP-55: `Keccak-256` sobre la cadena ASCII hexadecimal en
 * **minúsculas y sin `0x`**; cada dígito pasa a mayúscula si el nibble correspondiente
 * del hash es >= 8 (HU-06-02 RN-4).
 *
 * Acepta la entrada con o sin prefijo `0x` y en cualquier capitalización.
 */
export function toChecksumAddress(address: string): string {
  const raw = address.startsWith('0x') || address.startsWith('0X') ? address.slice(2) : address;
40→  if (!/^[0-9a-fA-F]{40}$/u.test(raw)) {
    throw validationError(
      [{ field: 'address', message: 'La dirección debe ser 0x + 40 dígitos hexadecimales.' }],
      'Dirección Ethereum con formato inválido.',
    );
  }

  const lower = raw.toLowerCase();
  const hash = toHex(keccak_256(ascii.encode(lower)));

50→  let out = '0x';
  for (let i = 0; i < lower.length; i += 1) {
    const char = lower[i] as string;
    const nibble = Number.parseInt(hash[i] as string, 16);
    out += nibble >= 8 ? char.toUpperCase() : char;
  }
  return out;
}

/**
60→ * `true` si la dirección está bien formada **y** su capitalización es exactamente la del
 * checksum EIP-55. Una dirección all-lowercase o all-uppercase no supera esta prueba
 * (salvo el caso degenerado de una dirección sin dígitos `a-f`, en el que las tres formas
 * coinciden por definición del propio EIP-55).
 */
export function isValidChecksumAddress(address: string): boolean {
  if (!isValidAddressFormat(address)) return false;
  return address === toChecksumAddress(address);
}

70→/**
 * Dirección Ethereum a partir de la clave pública secp256k1 sin comprimir en formato
 * `X ‖ Y` (64 bytes, sin el prefijo `0x04`): últimos 20 bytes de `Keccak-256(X ‖ Y)`,
 * devueltos con checksum EIP-55 (HU-06-02 RN-4).
 */
export function publicKeyToAddress(publicKeyXY: Uint8Array): string {
  if (publicKeyXY.length !== 64) {
    throw new Error(
      `La clave pública debe tener 64 bytes (X ‖ Y); se recibieron ${publicKeyXY.length}.`,
    );
80→  }
  const hash = keccak_256(publicKeyXY);
  return toChecksumAddress(toHex(hash.slice(hash.length - ADDRESS_BYTES)));
}

