}

/** `ser256`: serializa un entero como 32 bytes big-endian. */
function ser256(value: bigint): Uint8Array {
  const out = new Uint8Array(32);
  let rest = value;
  for (let i = 31; i >= 0; i -= 1) {
    out[i] = Number(rest & 0xffn);
    rest >>= 8n;
  }
  return out;
}

/** `ser32`: serializa un entero de 32 bits como 4 bytes big-endian. */
function ser32(value: number): Uint8Array {
  const out = new Uint8Array(4);
  new DataView(out.buffer).setUint32(0, value, false);
  return out;
}

/** `serP(point(k))`: clave pública secp256k1 comprimida (33 bytes), usada por CKDpriv normal. */
function serializedPoint(privateKey: Uint8Array): Uint8Array {
  return secp256k1.getPublicKey(privateKey, true);
}

/** Clave pública secp256k1 **sin comprimir**: 65 bytes, prefijo `0x04` ‖ X ‖ Y. */
export function publicKeyUncompressed(privateKey: Uint8Array): Uint8Array {
  return secp256k1.getPublicKey(privateKey, false);
}

/**
 * Coordenadas de la clave pública secp256k1: 64 bytes `X ‖ Y` (descartando el prefijo
 * `0x04`). Es la entrada de Keccak-256 para computar la dirección (HU-06-02 RN-4).
 */
export function publicKeyXY(privateKey: Uint8Array): Uint8Array {
  return publicKeyUncompressed(privateKey).slice(1);
}

/** Ejecuta HMAC-SHA512 vía el objeto `primitives` (stubbeable, ver AT-06-02-08). */
function hmac512(key: Uint8Array, data: Uint8Array): { left: Uint8Array; right: Uint8Array } {
  const I = primitives.hmacSha512(key, data);
  if (I.length !== 64) {
    throw new Error(`HMAC-SHA512 devolvió ${I.length} bytes; se esperaban 64.`);
  }
  return { left: I.slice(0, 32), right: I.slice(32, 64) };
}

/**
 * Clave maestra BIP-32 desde la seed binaria (HU-06-02 RN-1):
 * `I = HMAC-SHA512(key = "Bitcoin seed", data = seed)`, con `I_L` = clave privada maestra
 * e `I_R` = chain code maestro. Se valida `1 <= parse256(I_L) < n`.
 */
export function masterKeyFromSeed(seed: Uint8Array): HdNode {
  if (seed.length < 16 || seed.length > 64) {
    throw new Error(`Seed BIP-32 de longitud inválida: ${seed.length} bytes (admitido 16..64).`);
  }
  const { left, right } = hmac512(MASTER_KEY_SALT, seed);
  const k = parse256(left);
  if (k === 0n) throw new InvalidMasterKeyError('parse256(I_L) == 0');
  if (k >= SECP256K1_ORDER) throw new InvalidMasterKeyError('parse256(I_L) >= n');
  return { privateKey: left, chainCode: right };
}

/**
 * CKDpriv: clave privada hija a partir de la privada padre (HU-06-02 RN-3).
 *
 * - Hardened (`i >= 2³¹`): `I = HMAC-SHA512(c_par, 0x00 ‖ ser256(k_par) ‖ ser32(i))`.
 * - Normal   (`i <  2³¹`): `I = HMAC-SHA512(c_par, serP(point(k_par)) ‖ ser32(i))`.
 *
 * `k_hijo = (parse256(I_L) + k_par) mod n`, `c_hijo = I_R`. Si `parse256(I_L) >= n` o
 * `k_hijo == 0`, la clave es inválida y se lanza {@link InvalidChildKeyError} (RN-8).
 */
export function ckdPriv(node: HdNode, index: number): HdNode {
  if (!Number.isInteger(index) || index < 0 || index > MAX_INDEX) {
    throw new Error(`Índice BIP-32 fuera de rango: ${index}.`);
  }

  const data =
    index >= HARDENED_OFFSET
      ? concat(new Uint8Array([0x00]), node.privateKey, ser32(index))
      : concat(serializedPoint(node.privateKey), ser32(index));

  const { left, right } = hmac512(node.chainCode, data);

  const il = parse256(left);
  if (il >= SECP256K1_ORDER) throw new InvalidChildKeyError(index, 'parse256(I_L) >= n');

  const childKey = (il + parse256(node.privateKey)) % SECP256K1_ORDER;
  if (childKey === 0n) throw new InvalidChildKeyError(index, 'k_hijo == 0');

  return { privateKey: ser256(childKey), chainCode: right };
}

function concat(...parts: readonly Uint8Array[]): Uint8Array {
  const total = parts.reduce((acc, part) => acc + part.length, 0);
  const out = new Uint8Array(total);
  let offset = 0;
  for (const part of parts) {
    out.set(part, offset);
    offset += part.length;
  }
  return out;
}

/**
 * Parsea un path BIP-32 tipo `m/44'/60'/0'/0/0` a la lista de índices ya resueltos
 * (los componentes hardened suman `HARDENED_OFFSET`). Se aceptan `'` y `h`/`H` como
 * marca de hardened.
 */
export function parsePath(path: string): number[] {
  const trimmed = path.trim();
  const parts = trimmed.split('/');
  const head = parts[0];
  if (head !== 'm' && head !== 'M') {
    throw new Error(`Path BIP-32 inválido: "${path}" (debe empezar con "m").`);
  }

  return parts.slice(1).map((component) => {
    const match = /^(\d+)(['hH])?$/u.exec(component);
    if (match === null) {
      throw new Error(`Path BIP-32 inválido: componente "${component}" en "${path}".`);
    }
    const value = Number(match[1]);
    if (!Number.isInteger(value) || value >= HARDENED_OFFSET) {
      throw new Error(`Path BIP-32 inválido: índice "${component}" fuera de rango en "${path}".`);
    }
    return match[2] === undefined ? value : value + HARDENED_OFFSET;
  });
}

/**
 * Deriva el nodo correspondiente a `path` desde la seed binaria. Función **pura** de
 * `(seed, path)`: mismas entradas ⇒ mismas salidas siempre (HU-06-02 RN-5, INV-8).
 */
export function derivePath(seed: Uint8Array, path: string): HdNode {
  const indexes = parsePath(path);
  let node = masterKeyFromSeed(seed);
  for (let depth = 1; depth <= indexes.length; depth += 1) {
    try {
      node = ckdPriv(node, indexes[depth - 1] as number);
    } catch (error) {
      // Se anota el nivel del path para que el llamador distinga un fallo en el último
      // componente (el `address_index`, recuperable avanzando al siguiente) de uno en un
      // componente intermedio del path BIP-44, que es fijo y por lo tanto irrecuperable.
      if (error instanceof InvalidChildKeyError) error.depth = depth;
      throw error;
    }
  }
  return node;
}

