/**
 * Función pura de alto nivel de la épica 06: `(seed, address_index)` ⇒ dirección de
 * depósito Ethereum, siguiendo el path BIP-44 estándar de Ethereum.
 *
 * Fuente normativa: BIP-32, BIP-44 (coin type 60 / SLIP-44), EIP-55.
 * Spec del proyecto: HU-06-02 RN-2 (path `m/44'/60'/0'/0/address_index`),
 * RN-4 (dirección + checksum EIP-55), RN-5 (determinismo / INV-8),
 * RN-6 (custodia: la clave privada no sale de aquí), RN-8 (salto de índice inválido)
 * y RN-9 (rango no-hardened del `address_index`); HU-06-03 RN-1 y RN-13.
 */
import { AppError, validationError } from '../../shared/errors.js';
import { publicKeyToAddress } from './address.js';
import { HARDENED_OFFSET, InvalidChildKeyError, derivePath, publicKeyXY } from './bip32.js';

/** Path base BIP-44 de Ethereum, sin el `address_index` (HU-06-02 RN-2). */
export const ETHEREUM_BASE_PATH = "m/44'/60'/0'/0";

/**
 * Nivel (1-based) que ocupa el `address_index` dentro de `m/44'/60'/0'/0/{address_index}`.
 * Los niveles 1..4 (`44'`, `60'`, `0'`, `0`) son **fijos** por BIP-44: su cómputo HMAC no
 * depende del `address_index`.
 */
const ADDRESS_INDEX_DEPTH = 5;

/** Coin type de Ethereum según SLIP-44 (00-fundaciones/activos-y-par-de-trading §1). */
export const COIN_TYPE = 60;

/** chainId de la red única del proyecto: Sepolia (HU-06-02 RN-7, INV-6). */
export const CHAIN_ID = 11_155_111;

/** Último índice del espacio **no-hardened** de BIP-32: 2³¹ − 1 (HU-06-02 RN-9). */
export const MAX_ADDRESS_INDEX = HARDENED_OFFSET - 1;

/** Resultado de una derivación. No incluye la clave privada (HU-06-02 RN-6). */
export interface DerivedAccount {
  readonly addressIndex: number;
  readonly address: string;
  readonly derivationPath: string;
  readonly publicKeyXY: Uint8Array;
}

/** Path completo `m/44'/60'/0'/0/{addressIndex}` para un índice ya validado. */
export function derivationPathFor(addressIndex: number): string {
  assertAddressIndexInRange(addressIndex);
  return `${ETHEREUM_BASE_PATH}/${addressIndex}`;
}

/**
 * Valida que `address_index` sea entero en `[0, 2³¹ − 1]` (HU-06-02 RN-9). Un índice
 * `>= 2³¹` produciría silenciosamente una derivación hardened, así que se rechaza con
 * `VALIDATION_ERROR` (HTTP 422) **antes** de intentar derivar.
 */
export function assertAddressIndexInRange(addressIndex: number): void {
  if (
    !Number.isInteger(addressIndex) ||
    addressIndex < 0 ||
    addressIndex > MAX_ADDRESS_INDEX
