export const PROJECT_ENTROPY_BITS = 256;

/** Longitud de mnemonic exigida por la política del proyecto (HU-06-01 RN-2.a). */
export const PROJECT_MNEMONIC_WORDS = 24;

/** Parámetros de PBKDF2 fijados por BIP-39 (HU-06-01 RN-3). */
export const PBKDF2_ITERATIONS = 2048;
export const SEED_BYTES = 64;
30→
/** Prefijo del salt de PBKDF2 según BIP-39: `"mnemonic" + passphrase`. */
const SALT_PREFIX = 'mnemonic';

const utf8 = new TextEncoder();

export type MnemonicValidation =
  | { ok: true }
  | { ok: false; reason: 'LENGTH' | 'WORDLIST' | 'CHECKSUM' };

40→/**
 * Normalización Unicode NFKD del mnemonic (BIP-39, «From mnemonic to seed»: la frase se usa
 * como password de PBKDF2 **en UTF-8 NFKD**, sin ninguna otra transformación).
 *
